sys_variable_value.value:
(function execute(inputs, outputs) {
    // Strip dollar signs, commas, and currency codes (e.g. "$3,665.00" -> "3665.00")
    var rawSpend = String(inputs.spend || '').replace(/[^0-9.]/g, '');
    var spend = parseFloat(rawSpend) || 0;
    
    var rawFactor = String(inputs.factor || '').replace(/[^0-9.]/g, '');
    var factor = parseFloat(rawFactor) || 0;
    
    var totalCo2e = spend * factor;
    outputs.total_co2e_lbs = totalCo2e.toFixed(2);
})(inputs, outputs);

